var search_products_default = defineTool({
  name: "search_products",
  title: "Search OGURA products",
  description: "Search live OGURA products by keyword, category, or price range. Returns a list of products with id, title, price, category, and description.",
  inputSchema: {
    query: z.string().trim().optional().describe("Keyword to match against product title or description."),
    category: z.string().trim().optional().describe("Category slug or name to filter by."),
    max_price: z.number().int().positive().optional().describe("Maximum price in INR."),
    limit: z.number().int().min(1).max(50).optional().describe("Max number of results (default 20).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ query, category, max_price, limit }, ctx) => {
    const supabase = supabaseOptionalUser(ctx);
    let q = supabase.from("products").select("id, title, price, category, short_description, description, images").eq("status", "live").limit(limit ?? 20);
    if (query) q = q.or(`title.ilike.%${query}%,description.ilike.%${query}%`);
    if (category) q = q.eq("category", category);
    if (max_price) q = q.lte("price", max_price);
    const { data, error } = await q;
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? []) }],
      structuredContent: { products: data ?? [] }
    };
  }
});

// src/lib/mcp/tools/get-product.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z2 } from "npm:zod@^3.23.8";
var get_product_default = defineTool2({
  name: "get_product",
  title: "Get an OGURA product",
  description: "Fetch full details for a single OGURA product by its id.",
  inputSchema: {
    product_id: z2.string().uuid().describe("The product's UUID.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ product_id }, ctx) => {
    const { data, error } = await supabaseOptionalUser(ctx).from("products").select("*").eq("id", product_id).maybeSingle();
    if (error) return { content: [{ type: "text", text: error.message }], isError: true };
    if (!data) return { content: [{ type: "text", text: "Product not found." }], isError: true };
    return {
      content: [{ type: "text", text: JSON.stringify(data) }],
      structuredContent: { product: data }
    };
  }
});

