import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z3 } from "npm:zod@^3.23.8";
var list_my_orders_default = defineTool3({
  name: "list_my_orders",
  title: "List my OGURA orders",
  description: "List the signed-in OGURA customer's own orders, most recent first. Requires authentication.",
  inputSchema: {
    limit: z3.number().int().min(1).max(50).optional().describe("Max number of orders to return (default 10).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: async ({ limit }, ctx) => {
    if (!ctx.isAuthenticated()) {
      return {
        content: [{ type: "text", text: "You must be signed in to view your orders." }],
        isError: true
      };
    }
    const { data, error } = await supabaseForUser(ctx).from("orders").select(
      "id, order_number, status, subtotal, shipping_fee, discount, total, tracking_id, created_at"
    ).eq("customer_id", ctx.getUserId()).order("created_at", { ascending: false }).limit(limit ?? 10);
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? []) }],
      structuredContent: { orders: data ?? [] }
    };
  }
});

